rules.text:
# Rapid sequential ID enumeration
# Matches the automated crawl pattern: rapid sequential requests to resource-specific endpoints (shipments/PRO-, customers/101-110, drivers/E10) using a distinctive scanner User-Agent (AppleWebKit/537.3
set $mr_1748085 "";
if ($request_method = GET) { set $mr_1748085 "${mr_1748085}M"; }
if ($uri ~* "^/(shipments|customers|drivers)/[A-Z0-9-]+$") { set $mr_1748085 "${mr_1748085}P"; }
if ($http_user_agent ~* "AppleWebKit/537\\.36 \\(KHTML") { set $mr_1748085 "${mr_1748085}U"; }
if ($mr_1748085 = "MPU") { return 403; }

# Sensitive file probe
# Attackers request well-known sensitive files at root level (.env, .git/config, backup.zip, db.sql) that legitimate users never access legitimate zip files are under /downloads/.
set $mr_1094923 "";
if ($request_method = GET) { set $mr_1094923 "${mr_1094923}M"; }
if ($uri ~* "^/\\.(env|git/config)$|^/backup\\.zip$|^/db\\.sql$") { set $mr_1094923 "${mr_1094923}P"; }
if ($mr_1094923 = "MP") { return 403; }

# Admin panel enumeration
# Scanners systematically probe common admin panel paths legitimate traffic uses deeper, application-specific routes like /admin/audit.
set $mr_1536110 "";
if ($request_method = GET) { set $mr_1536110 "${mr_1536110}M"; }
if ($uri ~* "^/(admin|administrator|wp-login\\.php|phpmyadmin|console|server-status|cgi-bin|info\\.php|test)/?$") { set $mr_1536110 "${mr_1536110}P"; }
if ($mr_1536110 = "MP") { return 403; }

# Injection payloads on auth endpoints
# Attackers append SQLi, path traversal, and XSS payloads to login/admin endpoints benign requests only carry harmless paging or tracking parameters.
# note: nginx sees $args URL-encoded, so encoded variants may need extra patterns
set $mr_1283502 "";
if ($request_method = GET) { set $mr_1283502 "${mr_1283502}M"; }
if ($uri ~* "^/(admin|login)/?$") { set $mr_1283502 "${mr_1283502}P"; }
if ($args ~* "(\\b|[?&])(id|file|q)=([^&]*(\\'|\\.\\./|<script|alert\\())") { set $mr_1283502 "${mr_1283502}Q"; }
if ($mr_1283502 = "MPQ") { return 403; }
